import{d as g,C as e,o as h,c as d,j as i,a,E as t,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"中庸·第12章","description":"《中庸》第 12 章——君子之道费而隐：夫妇可与知能行，其至则圣人有所不知不能；鸢飞鱼跃，上下昭著。","frontmatter":{"title":"中庸·第12章","description":"《中庸》第 12 章——君子之道费而隐：夫妇可与知能行，其至则圣人有所不知不能；鸢飞鱼跃，上下昭著。","category":"guide","aliases":["第12章","中庸第12章","费而隐"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-12.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-12.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-12.md"},b=g({...m,setup(p){const o=[{id:"feiyin",label:"费而隐 · 夫妇可与知能行",showLabel:!0,sentences:[["君子之道",{text:"费而隐",glossary:"feiyin"},"。",{text:"夫妇",glossary:"fufu"},"之愚，可以",{text:"与知",glossary:"yuzhi"},"焉；及其至也，虽圣人亦有所不知焉。夫妇之不肖，可以能行焉；及其至也，虽圣人亦有所不能焉。"]],note:"「君子之道费而隐」——君子之道，其用广大（费），其体精微（隐）。从近处说：寻常夫妇（愚者）也可以知道、可以实行；推到极处：即使圣人也有所不知、有所不能。此章总说君子之道「大而无外、细而无内」。"},{id:"daxiao",label:"语大莫能载 · 语小莫能破",showLabel:!0,sentences:[["天地之大也，人犹有所",{text:"憾",glossary:"han"},"。故君子语大，天下莫能",{text:"载",glossary:"zai"},"焉；语小，天下莫能",{text:"破",glossary:"po"},"焉。"]],note:"「天地之大也，人犹有所憾」——天地如此之大，人尚且有所不满足。故「君子语大，天下莫能载焉；语小，天下莫能破焉」：说它大，天下载不住；说它小，天下分不开。"},{id:"yuanfei",label:"鸢飞鱼跃 · 造端乎夫妇，察乎天地",showLabel:!0,sentences:[["《诗》云：“",{text:"鸢飞戾天",glossary:"yuanfei"},"，鱼跃于渊。”言其上下",{text:"察",glossary:"cha"},"也。君子之道，",{text:"造端",glossary:"zaoduan"},"乎夫妇；及其至也，察乎天地。"]],note:"引《诗》「鸢飞戾天，鱼跃于渊」——鸢飞上天、鱼跃深渊，说的正是道的「上下昭著」。故「君子之道，造端乎夫妇；及其至也，察乎天地」：从夫妇日用开端，推到极处则昭著于天地之间。"}],r=[{id:"feiyin",term:"费而隐",pinyin:"fèi ér yǐn",meaning:"朱注：「费，用之广也；隐，体之微也。」用途广大而本体精微——全章由此一对概念展开。"},{id:"fufu",term:"夫妇",pinyin:"fū fù",meaning:"匹夫匹妇，即普通人。朱注：「近自夫妇居室之间。」"},{id:"yuzhi",term:"与知",pinyin:"yù zhī",meaning:"参与、知道。与：读 yù（参与）。"},{id:"han",term:"憾",pinyin:"hàn",meaning:"遗憾、不满。朱注举「覆载生成之偏，及寒暑灾祥之不得其正者」。"},{id:"zai",term:"载",pinyin:"zài",meaning:"承载。语大而天下莫能载，极言其大。"},{id:"po",term:"破",pinyin:"pò",meaning:"剖分、说破。语小而天下莫能破，极言其小。"},{id:"yuanfei",term:"鸢飞戾天",pinyin:"yuān fēi lì tiān",meaning:"鸢（鸱类）飞至于天。戾：至。《诗·大雅·旱麓》句。"},{id:"cha",term:"察",pinyin:"chá",meaning:"昭著、显明。上下察，谓化育流行、上下昭著，莫非此理之用。"},{id:"zaoduan",term:"造端",pinyin:"zào duān",meaning:"开始、发端。"}];return(y,n)=>{const s=e("DaoTextReading"),l=e("DaoKeywordCards");return h(),d("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第12章",tabindex:"-1"},[a("中庸·第12章 "),i("a",{class:"header-anchor",href:"#中庸·第12章","aria-label":'Permalink to "中庸·第12章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[a("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[a("第十二章立起一对概念——"),i("strong",null,"费"),a("（用之广）与"),i("strong",null,"隐"),a("（体之微）：普通男女皆能知能行，推到极处连圣人也有不知不能；而「鸢飞鱼跃」，正是这道理上下昭著的样子。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),t(s,{colophon:"费而隐 · 鸢飞鱼跃 · 察乎天地",tone:"ink",sections:o,glossary:r,"default-mode":"slips","aria-label":"中庸·第12章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[a("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),t(l,{items:[{term:"费而隐",pinyin:["fèi","ér","yǐn"],meaning:"朱注：「费，用之广也；隐，体之微也。」一广一微，是全章的两端。"},{term:"夫妇",pinyin:["fū","fù"],meaning:"匹夫匹妇，普通人。朱注：「近自夫妇居室之间。」"},{term:"与知",pinyin:["yù","zhī"],meaning:"参与、知道。与：读 yù。"},{term:"憾",pinyin:["hàn"],meaning:"遗憾、不满。"},{term:"鸢飞戾天",pinyin:["yuān","fēi","lì","tiān"],meaning:"鸢（鸱类）飞至于天。戾：至。"},{term:"造端",pinyin:["zào","duān"],meaning:"开始、发端。「造端乎夫妇，及其至也，察乎天地」——两端都被点到。"}]}),n[4]||(n[4]=u("",25))])}}});export{c as __pageData,b as default};
